// ===== CUSTOMER JOURNEYS SYNC =====
// Weekly. Adds NEW customers (lifecycle stage 'customer') closed since 2026-01-01,
// flips status on churn; existing rows otherwise stay untouched.
const ANTHROPIC_MODEL = 'claude-sonnet-5';
const BACKFILL_FROM = '2026-01-01';
return [{ json: { ANTHROPIC_MODEL, BACKFILL_FROM } }];

const opts = (($('Get Lifecycle Labels').first().json || {}).options || []);
const cust = opts.find(o => String(o.value).toLowerCase() === 'customer' || /^customer$/i.test(o.label)) || { value: 'customer' };
const churn = opts.find(o => /churn/i.test(String(o.label)) || /churn/i.test(String(o.value)));
const values = [String(cust.value)]; if (churn) values.push(String(churn.value));
return [{ json: { churnValue: churn ? String(churn.value) : null, body: {
  filterGroups: [{ filters: [{ propertyName: 'lifecyclestage', operator: 'IN', values }] }],
  properties: ['name','lifecyclestage','publisher_type','geoplitical_region','hs_analytics_source','hs_analytics_source_data_1','hs_v2_date_entered_customer','createdate','hubspot_owner_id'],
  sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }], limit: 100 } } }];

const cfg = $('Config').first().json;
const churnValue = $('Build Cust Search').first().json.churnValue;
const existing = {};
for (const it of $('Read Existing').all()) if (it.json && it.json.company_id) existing[String(it.json.company_id)] = it.json.status;
const rows = [];
const seen = new Set();
for (const it of $('Search Customers').all()) for (const r of (it.json.results || [])) {
  if (seen.has(r.id)) continue; seen.add(r.id);
  const p = r.properties || {};
  const status = churnValue && String(p.lifecyclestage) === churnValue ? 'churned' : 'customer';
  const closed = p.hs_v2_date_entered_customer ? String(p.hs_v2_date_entered_customer).slice(0, 10) : null;
  if (!closed || closed < cfg.BACKFILL_FROM) continue;  // no verified 2026+ close -> outside backfill window
  rows.push({ id: String(r.id), name: p.name || '', status, closed,
    icp: p.publisher_type || null, region: p.geoplitical_region || null,
    srcType: p.hs_analytics_source || null, srcDetail: p.hs_analytics_source_data_1 ? String(p.hs_analytics_source_data_1).slice(0, 80) : null,
    created: p.createdate ? String(p.createdate).slice(0, 10) : null, ownerId: p.hubspot_owner_id || null });
}
const toProcess = rows.filter(r => !(r.id in existing));
const statusFlips = rows.filter(r => r.id in existing && existing[r.id] !== r.status)
  .map(r => ({ id: r.id, status: r.status }));
const ids = toProcess.map(r => r.id);
const activityQuery = ids.length ? [
  "SELECT company_id::text AS cid, 'call' AS k, jsonb_build_object('ts', ts, 'bucket', bucket, 'label', disposition_label, 'contact', contact_name) AS j FROM calls WHERE company_id IN (" + ids.join(',') + ")",
  "SELECT company_id::text, 'disc', jsonb_build_object('ts', meeting_start, 'status', status, 'note', outcome_note, 'topic', topic, 'contacts', contact_name, 'conv', conversions) FROM discoveries WHERE company_id IN (" + ids.join(',') + ")",
  "SELECT company_id::text, 'deal', jsonb_build_object('created', create_date, 'close', close_date, 'lstart', license_start, 'mrr', mrr, 'name', deal_name, 'type', dealtype, 'won', is_won, 'wasclosed', is_closed, 'partner', partner_name) FROM deals_mirror WHERE company_id IN (" + ids.join(',') + ")",
  "SELECT company_id::text, 'stage', jsonb_build_object('ts', effective_date, 'stage', stage) FROM company_stage_entries WHERE company_id IN (" + ids.join(',') + ")",
  "SELECT company_id::text, 'reply', jsonb_build_object('ts', date, 'contact', contact_name) FROM email_replies WHERE company_id IN (" + ids.join(',') + ")",
  "SELECT company_id::text, 'seqmail', jsonb_build_object('ts', first_sent) FROM sequence_companies WHERE company_id IN (" + ids.join(',') + ")"
].join(' UNION ALL ') : "SELECT '0' AS cid, 'none' AS k, '{}'::jsonb AS j WHERE false";
return [{ json: { toProcess, statusFlips, activityQuery, any: toProcess.length > 0 } }];

const d = $('Diff New').first().json;
if (!d.any) return [{ json: { skip: true, id: null, body: { filterGroups: [], limit: 1 } } }];
return d.toProcess.map(r => { const f = [
  { propertyName: 'associations.company', operator: 'EQ', value: r.id },
  { propertyName: 'hs_email_direction', operator: 'EQ', value: 'EMAIL' }];
  if (r.closed) f.push({ propertyName: 'hs_timestamp', operator: 'LT', value: String(Date.parse(r.closed) + 86400000) });
  return { json: { id: r.id, body: { filterGroups: [{ filters: f }], properties: ['hs_object_id'], limit: 1 } } };
});

const d = $('Diff New').first().json;
const cfg = $('Config').first().json;
if (!d.any) return [{ json: { has: false, rows: [], statusFlips: d.statusFlips } }];
const OWNERS = {};
try { for (const it of $('Get Owners').all()) for (const o of ((it.json || {}).results || []))
  OWNERS[String(o.id)] = [o.firstName, o.lastName].filter(Boolean).join(' ') || (o.email || ''); } catch (e) {}
const emailTotals = {};
{ const reqs = $('Build Email Counts').all();
  $('Count Emails').all().forEach((it, i) => {
    const id = (reqs[i] && reqs[i].json.id) || null;
    if (id) emailTotals[id] = Number((it.json || {}).total) || 0; }); }
const act = {};
for (const it of $('Read Activity').all()) {
  const r = it.json; if (!r || !r.cid) continue;
  (act[r.cid] = act[r.cid] || []).push(Object.assign({ k: r.k }, r.j || {}));
}
const DAY = 86400000;
const rows = [];
for (const c of d.toProcess) {
  const ev = [];
  const a = act[c.id] || [];
  const close = c.closed;
  const cutoff = close ? close + 'T23:59' : '9999';
  const champCount = {};
  let calls = 0, connected = 0, meetings = 0;
  if (c.created) ev.push({ ts: c.created, kind: 'created', label: 'Record created' });
  for (const x of a) {
    const ts = String(x.ts || x.created || '').slice(0, 10);
    if (!ts) continue;
    if (x.k === 'call') {
      if (ts <= cutoff) { calls++; if (x.bucket === 'connected') connected++; }
      ev.push({ ts, kind: x.bucket === 'connected' ? 'conn' : 'call', label: x.label || 'Call', who: x.contact || null });
    } else if (x.k === 'disc') {
      if (x.status !== 'canceled' && ts <= cutoff) meetings++;
      ev.push({ ts, kind: 'meeting', label: x.topic || x.note || 'Discovery meeting', who: x.contacts || null });
      for (const nm of String(x.contacts || '').split(',').map(s => s.trim()).filter(Boolean))
        champCount[nm] = (champCount[nm] || 0) + 2;
      for (const part of String(x.conv || '').split(';').filter(Boolean)) {
        const bits = part.split('|');
        if (bits[1]) ev.push({ ts: bits[1], kind: bits[0] === 'download' ? 'download' : bits[0] === 'event' ? 'event' : 'form', label: bits[2] || bits[0] });
      }
    } else if (x.k === 'deal') {
      if (x.created) ev.push({ ts: String(x.created), kind: 'deal', label: 'Deal created: ' + (x.name || '') });
      if (x.close && x.wasclosed) ev.push({ ts: String(x.close), kind: x.won ? 'won' : 'lost', label: (x.won ? 'Won: ' : 'Lost: ') + (x.name || '') });
    } else if (x.k === 'stage') {
      ev.push({ ts, kind: 'stage', label: 'Entered ' + x.stage });
    } else if (x.k === 'reply') {
      ev.push({ ts, kind: 'reply', label: 'Replied' + (x.contact ? ': ' + x.contact : '') });
      if (x.contact) champCount[x.contact] = (champCount[x.contact] || 0) + 1;
    } else if (x.k === 'seqmail') {
      ev.push({ ts, kind: 'email', label: 'Outreach sequence started' });
    }
  }
  const deals = a.filter(x => x.k === 'deal');
  const wonSorted = deals.filter(x => x.won).sort((p, q) => String(p.close || '') < String(q.close || '') ? -1 : 1);
  const wonFL = wonSorted.find(x => /new|full|license/i.test(String(x.type || ''))) || wonSorted[0] || null;
  const firstDeal = deals.map(x => String(x.created || '')).filter(Boolean).sort()[0] || null;
  const firstDisc = a.filter(x => x.k === 'disc' && x.status !== 'canceled').map(x => String(x.ts).slice(0, 10)).sort()[0] || null;
  const touchDates = ev.filter(e => ['call','conn','email','download','form','event','reply'].includes(e.kind)).map(e => e.ts).sort();
  const firstTouch = touchDates[0] || c.created || firstDeal;
  // first-became-customer: EARLIEST of all signals; renewals/merges only push dates later
  const custEntries = a.filter(x => x.k === 'stage' && /customer/i.test(String(x.stage)) && !/churn/i.test(String(x.stage)))
    .map(x => String(x.ts).slice(0, 10));
  const flWon = deals.filter(x => x.won && /new|full|license/i.test(String(x.type || '')) && !/renewal|existing|bestand|upsell/i.test(String(x.type || '')));
  const wonCloses = flWon.map(x => x.lstart || x.close).filter(Boolean).map(x => String(x).slice(0, 10));
  const preCustomer = deals.some(x =>
    (x.won && x.lstart && String(x.lstart).slice(0, 10) < cfg.BACKFILL_FROM) ||
    (x.won && x.close && String(x.close).slice(0, 10) < cfg.BACKFILL_FROM) ||
    (/renewal|existing|bestand|upsell/i.test(String(x.type || '')) && x.created && String(x.created).slice(0, 10) < cfg.BACKFILL_FROM));
  if (preCustomer) continue;  // was a customer before the backfill window; belongs to an earlier cohort
  const closeCands = [...custEntries, ...wonCloses, close].filter(Boolean).sort();
  const closeDate = closeCands[0] || (wonFL && wonFL.close ? String(wonFL.close) : null);
  if (!closeDate || closeDate < cfg.BACKFILL_FROM) continue;  // true first close outside window (e.g. merge reset the HubSpot date)
  const lt = wonFL ? String(wonFL.type || '') : '';
  const licenseType = !wonFL ? null : /light/i.test(lt) ? 'JENTIS Light' : /poc|pilot|test/i.test(lt) ? 'POC'
    : /renewal|existing|bestand|upsell/i.test(lt) ? 'Renewal' : /new|full|license/i.test(lt) ? 'Full License' : (lt || null);
  const dd = (a2, b2) => { if (!a2 || !b2) return null; const v = Math.round((Date.parse(b2) - Date.parse(a2)) / DAY); return v < 0 ? null : v; };
  const champions = Object.entries(champCount).sort((p, q) => q[1] - p[1]).slice(0, 3).map(p => p[0]).join('; ') || null;
  const partner = (deals.find(x => x.partner) || {}).partner || null;
  ev.sort((p, q) => p.ts < q.ts ? -1 : 1);
  const evCut = ev.filter(e => e.ts <= (closeDate ? closeDate + 'T23' : '9999')).slice(0, 300);
  rows.push({ id: c.id, name: c.name, status: c.status, icp: c.icp, region: c.region,
    srcType: c.srcType, srcDetail: c.srcDetail,
    firstTouch, firstDisc, firstDeal, dealCreate: wonFL && wonFL.created ? String(wonFL.created) : null,
    closeDate, cycleDays: wonFL ? dd(wonFL.created, wonFL.close || closeDate) : null,
    journeyDays: dd(firstTouch, closeDate), ttDisc: dd(firstTouch, firstDisc),
    ttDeal: dd(firstTouch, firstDeal), ttClose: wonFL ? dd(wonFL.created, closeDate) : null,
    emails: emailTotals[c.id] != null ? emailTotals[c.id] : null, calls, connected, meetings,
    champions, partner, licenseType, ownerName: c.ownerId ? (OWNERS[String(c.ownerId)] || null) : null,
    mrr: wonFL && wonFL.mrr != null && !isNaN(Number(wonFL.mrr)) ? Number(wonFL.mrr) : null, events: evCut,
    meetingNotes: a.filter(x => x.k === 'disc').map(x => [String(x.ts).slice(0, 10), x.topic, x.note].filter(Boolean).join(' ')).slice(0, 8) });
}
return [{ json: { has: rows.length > 0, rows, statusFlips: d.statusFlips } }];

const st = $('Assemble').first().json;
if (!st.has) return [{ json: { has: false } }];
const cfg = $('Config').first().json;
const items = st.rows.map(r => ({ id: r.id, name: r.name, icp: r.icp, source: r.srcDetail || r.srcType,
  stats: { first_touch: r.firstTouch, close: r.closeDate, cycle_days: r.cycleDays, journey_days: r.journeyDays,
    emails: r.emails, calls: r.calls, connected: r.connected, meetings: r.meetings },
  champions: r.champions, partner: r.partner,
  meeting_notes: r.meetingNotes,
  key_events: (r.events || []).filter(e => ['reply','download','form','event','meeting'].includes(e.kind)).slice(0, 25)
    .map(e => e.ts + ' ' + e.kind + ': ' + String(e.label).slice(0, 70)) }));
const out = [];
for (let i = 0; i < items.length; i += 3) {
  out.push({ json: { has: true, body: { model: cfg.ANTHROPIC_MODEL, max_tokens: 3600, messages: [{ role: 'user', content:
    'You write compact customer-journey summaries for a B2B sales dashboard (JENTIS, server-side tracking). For each customer produce: ' +
    'pain (max 6 words: the concrete pain/topic actually discussed in meetings; null if there are no meeting notes - NEVER use deal names or deal types as pain) and story (max 120 words). The story must be QUALITATIVE, like a salesperson telling a colleague how the deal was won: WHY they came to us / what triggered interest, the pain and its urgency, what mattered to them, objections or blockers and how they were handled, who pushed it internally (names/titles), and what sealed it. Do NOT recite the timeline, meeting counts, or stage changes - the dashboard already shows those; only mention an event if something qualitatively important happened there. Pull substance from the meeting notes; if meeting_notes is empty or thin, the story MUST be 1-2 honest sentences (e.g. that the win happened with little recorded discovery context) - never fill space by listing deals, renewals, or stage changes. German notes -> answer in English. Plain prose, no bullets. ' +
    'Respond ONLY with a JSON array, no fences: [{"id":"...","pain":"...","story":"..."}]' +
    String.fromCharCode(10) + String.fromCharCode(10) + JSON.stringify(items.slice(i, i + 3)) } ] } } });
}
return out;

const esc = v => v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = v => v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v));
const st = $('Assemble').first().json;
const ai = {};
for (const it of $input.all()) {
  const content = it.json && it.json.content;
  if (!Array.isArray(content)) continue;
  let t = content.filter(c => c.type === 'text').map(c => c.text).join('');
  try {
    let tt = t.replace(/```json|```/g, '').trim();
    const a2 = tt.indexOf('['); if (a2 > 0) tt = tt.slice(a2, tt.lastIndexOf(']') + 1);
    for (const r of JSON.parse(tt)) ai[String(r.id)] = r;
  } catch (e) {}
}
const stmts = ['BEGIN;'];
for (const r of (st.rows || [])) {
  const a = ai[r.id] || {};
  stmts.push('INSERT INTO customer_journeys (company_id,name,status,icp,region,source_type,source_detail,first_touch,first_disc,first_deal,deal_create,close_date,cycle_days,journey_days,tt_disc,tt_deal,tt_close,emails,calls,connected,meetings,champions,partner_name,license_type,owner_name,mrr,pain,ai_story,events,updated_at) VALUES (' +
    [num(r.id), esc(r.name), esc(r.status), esc(r.icp), esc(r.region), esc(r.srcType), esc(r.srcDetail),
     esc(r.firstTouch), esc(r.firstDisc), esc(r.firstDeal), esc(r.dealCreate), esc(r.closeDate),
     num(r.cycleDays), num(r.journeyDays), num(r.ttDisc), num(r.ttDeal), num(r.ttClose),
     num(r.emails), num(r.calls), num(r.connected), num(r.meetings),
     esc(r.champions), esc(r.partner), esc(r.licenseType), esc(r.ownerName), num(r.mrr), esc(a.pain || null), esc(a.story || null),
     esc(JSON.stringify(r.events || [])) + '::jsonb', esc(new Date().toISOString())].join(',') +
    ') ON CONFLICT (company_id) DO UPDATE SET name=EXCLUDED.name, status=EXCLUDED.status, icp=EXCLUDED.icp, region=EXCLUDED.region, close_date=EXCLUDED.close_date, cycle_days=EXCLUDED.cycle_days, journey_days=EXCLUDED.journey_days, emails=EXCLUDED.emails, calls=EXCLUDED.calls, connected=EXCLUDED.connected, meetings=EXCLUDED.meetings, champions=EXCLUDED.champions, partner_name=EXCLUDED.partner_name, license_type=EXCLUDED.license_type, owner_name=EXCLUDED.owner_name, mrr=EXCLUDED.mrr, pain=COALESCE(EXCLUDED.pain, customer_journeys.pain), ai_story=COALESCE(EXCLUDED.ai_story, customer_journeys.ai_story), events=EXCLUDED.events, updated_at=EXCLUDED.updated_at;');
}
for (const f of (st.statusFlips || []))
  stmts.push("UPDATE customer_journeys SET status=" + esc(f.status) + ", churn_date=" + (f.status === 'churned' ? 'CURRENT_DATE' : 'NULL') + ", updated_at=now() WHERE company_id=" + num(f.id) + ";");
if (stmts.length <= 1) return [{ json: { sql: 'SELECT 1;' } }];
stmts.push('COMMIT;');
return [{ json: { sql: stmts.join(String.fromCharCode(10)) } }];
